import pyomo.environ as pyo

DATA = {
    "warehouses": ["A", "B"],
    "materials": ["A", "B", "C"],
    # freight cost per truck from each warehouse
    "cost": {"A": 200, "B": 160},
    # per-truck yield: yield[warehouse][material]
    "yield": {
        "A": {"A": 4, "B": 2, "C": 6},
        "B": {"A": 7, "B": 2, "C": 2},
    },
    # minimum required amount of each material
    "requirement": {"A": 240, "B": 80, "C": 120},
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.WAREHOUSES = pyo.Set(initialize=d["warehouses"])
    model.MATERIALS = pyo.Set(initialize=d["materials"])

    # Decision: number of trucks sent to each warehouse (integer, >= 0)
    model.trucks = pyo.Var(
        model.WAREHOUSES,
        within=pyo.NonNegativeIntegers,
    )

    # Objective: minimize total freight cost
    def obj_rule(m):
        return sum(d["cost"][w] * m.trucks[w] for w in m.WAREHOUSES)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Constraint: each material requirement must be met (>= requirement)
    def meet_requirement_rule(m, mat):
        return sum(
            d["yield"][w][mat] * m.trucks[w] for w in m.WAREHOUSES
        ) >= d["requirement"][mat]

    model.meet_requirement = pyo.Constraint(
        model.MATERIALS, rule=meet_requirement_rule
    )

    return model


